    answers = bearers.map do |bearer|
      get "/internal/v1/handoff/checkpoint", headers: bearer ? { "Authorization" => bearer } : {}
      [response.status, response.parsed_body]
    end

    expect(answers).to all(eq([401, { "reason" => "unauthorized" }]))
  end
end

